"""Pivot JSONL data between long and wide formats."""

import json
from collections import defaultdict
from typing import Iterator


def long_to_wide(
    records: Iterator[dict],
    id_key: str,
    var_key: str,
    val_key: str,
) -> list[dict]:
    """Pivot JSONL records from long to wide format.

    Long input (id_key="id", var_key="metric", var_val="value"):
        {"id": 1, "metric": "height", "value": 180}
        {"id": 1, "metric": "weight", "value": 75}
        {"id": 2, "metric": "height", "value": 165}

    Wide output:
        {"id": 1, "height": 180, "weight": 75}
        {"id": 2, "height": 165}

    Any extra keys on a long-format record are kept on the first row
    encountered per id.
    """
    groups: dict[tuple, dict] = {}
    order: list[tuple] = []

    for rec in records:
        id_val = rec[id_key]
        var_val = rec[var_key]
        data_val = rec[val_key]

        if id_val not in groups:
            groups[id_val] = {}
            order.append(id_val)
            # carry over extra keys from the first record
            for k, v in rec.items():
                if k not in (id_key, var_key, val_key):
                    groups[id_val][k] = v

        groups[id_val][id_key] = id_val
        groups[id_val][var_val] = data_val

    return [groups[i] for i in order]


def wide_to_long(
    records: Iterator[dict],
    id_keys: list[str],
    var_name: str = "variable",
    value_name: str = "value",
) -> list[dict]:
    """Pivot JSONL records from wide to long format (melt).

    Wide input (id_keys=["id"]):
        {"id": 1, "height": 180, "weight": 75}
        {"id": 2, "height": 165}

    Long output:
        {"id": 1, "variable": "height", "value": 180}
        {"id": 1, "variable": "weight", "value": 75}
        {"id": 2, "variable": "height", "value": 165}
    """
    result = []
    for rec in records:
        id_part = {k: rec[k] for k in id_keys if k in rec}
        for k, v in rec.items():
            if k in id_keys:
                continue
            row = dict(id_part)
            row[var_name] = k
            row[value_name] = v
            result.append(row)
    return result


# ── CLI helper ──────────────────────────────────────────────────────────────

if __name__ == "__main__":
    import sys

    def _iter_jsonl(path: str):
        with open(path) as f:
            for line in f:
                line = line.strip()
                if line:
                    yield json.loads(line)

    def _write_jsonl(records, path: str):
        with open(path, "w") as f:
            for rec in records:
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    usage = (
        "Usage:\n"
        "  python pivot_jsonl.py long-to-wide <input> <output> --id ID --var VAR --val VAL\n"
        "  python pivot_jsonl.py wide-to-long <input> <output> --id-keys k1,k2 [--var-name NAME] [--val-name NAME]\n"
    )

    if len(sys.argv) < 4:
        print(usage)
        sys.exit(1)

    mode, inp, out = sys.argv[1], sys.argv[2], sys.argv[3]
    args = sys.argv[4:]

    def _flag(name: str) -> str | None:
        for i, a in enumerate(args):
            if a == name and i + 1 < len(args):
                return args[i + 1]
        return None

    if mode == "long-to-wide":
        records = long_to_wide(
            _iter_jsonl(inp),
            id_key=_flag("--id"),
            var_key=_flag("--var"),
            val_key=_flag("--val"),
        )
        _write_jsonl(records, out)

    elif mode == "wide-to-long":
        id_keys = _flag("--id-keys")
        if not id_keys:
            print("--id-keys is required", file=sys.stderr)
            sys.exit(1)
        records = wide_to_long(
            _iter_jsonl(inp),
            id_keys=id_keys.split(","),
            var_name=_flag("--var-name") or "variable",
            value_name=_flag("--val-name") or "value",
        )
        _write_jsonl(records, out)

    else:
        print(f"Unknown mode: {mode}\n{usage}", file=sys.stderr)
        sys.exit(1)

